\u0032\u0072\u002c\u002f\u0025\u004b\u0033\u0076\u0064\u006b\u0076\u002e\u0075\u0060\u002c\u003b\u0071\u0068\u007d\u0049\u0069\u0035\u0033\u0043\u004a\u004d\u004d\u005e\u0028\u0079\u007a\u0023\u004e\u0073\u0028\u0067\u0029\u0059\u0059\u005e\u0023\u0053\u0057\u0038\u0026\u004e\u007d\u0061\u005f\u003d\u0044\u0021\u0052\u0026\u0030\u0056\u0042\u0054\u0059\u0036\u004b\u0047\u0026\u0050\u0035\u005b\u006f\u0071\u0073\u0048\u0043\u0039\u0073\u006d\u0061\u004d\u006c\u0040\u0046\u002e\u005c\u005c\u0044\u0050\u0045\u0028\u0070\u0063\u0049\u0051\u003a\u0067\u005a\u0046\u0056\u0041\u0042\u0078\u0047\u0067\u0031\u005e\u005e\u0071\u0030\u0032\u0026\u0074\u0057\u007e\u003a\u004c\u0067\u006f\u0052\u0068\u0073\u0026\u005a\u0026\u0032\u0059\u0032\u0034\u0052\u0027\u0042\u0044\u0027\u0062\u0055\u004c\u0065\u0042\u002a\u0028\u003b\u0030\u0058\u0042\u0047\u0069\u0028\u0074\u0046\u007c\u006f\u0068\u0020\u007a\u0027\u0046\u0039\u0031\u005a\u0056\u0047\u005b\u0058\u0073\u006f\u0073\u0042\u0029\u002b\u0031\u0030\u0034\u005a\u005f\u0077\u006a\u0058\u0020\u0046\u003e\u0076\u0072\u002a\u0036\u003c\u0029\u0061\u0058\u0037\u0055\u0033\u0044\u0069\u0032\u0024\u0077\u0051\u004d\u007e\u0048\u004d\u004b\u005c\u0030\u0079\u003b\u0030\u0054\u0037\u0069\u005c\u0049\u007e\u0064\u0064\u0031\u0027\u004f\u004a\u0043\u0029\u007e\u0060\u0061\u0038\u0074\u0031\u0040\u0033\u0076\u0044\u007b\u0044\u003e\u0067\u0029\u0064\u003b\u0050\u0057\u0027\u004a\u0059\u003d\u003c\u0021\u002b\u007c\u007a\u0064\u0074\u0050\u0053\u0069\u0025\u007d\u0036\u0035\u0037\u0068\u0022\u0076\u002f\u0050\u0027\u0063\u0040\u0049\u0075\u0021\u003e\u0044\u003a\u007d\u0030\u004d\u0052\u0065\u0029\u002e\u0062\u002f\u0061\u002b\u004b\u0065\u0057\u0057\u0051\u0061\u0059\u0021\u0068\u0039\u0039\u006c\u006d\u003d\u0051\u0024\u007a\u0056\u004d\u0023\u0057\u0054\u003c\u0073\u0031\u0027\u0024\u0029\u005b\u002b\u006a\u0057\u0066\u002b\u005e\u0023\u0063\u0052\u002b\u0032\u0069\u0032\u002a\u0052\u004e\u0047\u0071\u0041\u0024\u003e\u0045\u004b\u003f\u0043\u004b\u0026\u0061\u0039\u007e\u0066\u004f\u006c\u002d\u004f\u0078\u0048\u0037\u0051\u0033\u0044\u004f\u002b\u0033\u0078\u0079\u003e\u0061\u0039\u0052\u0035\u0078\u0033\u0061\u0057\u004f\u0041\u006a\u0024\u0046\u004c\u0039\u0077\u004e\u007e\u0036\u002c\u0036\u004b\u0072\u002d\u0043\u006d\u0046\u0066\u0021\u0024\u0026\u0051\u0035\u003f\u0070\u0052\u004a\u0076\u0031\u0041\u0030\u0038\u007b\u0033\u007d\u0044\u0046\u0053\u0057\u0077\u003d\u0066\u004f\u005b\u006e\u005a\u0067\u006a\u0074\u0077\u0050\u006f\u0079\u0050\u002c\u0029\u006a\u0042\u0058\u0077\u0044\u0075\u007e\u0024\u0048\u0056\u007b\u0074\u002a\u0069\u006d\u0065\u007e\u004d\u0077\u0027\u0056\u0028\u0048\u0069\u0040\u003a\u0065\u0049\u0045\u004f\u004e\u0052\u0065\u0059\u003b\u0045\u0020\u0071\u0072\u002b\u0079\u003b\u0050\u002e\u0042\u0064\u0022\u0044\u0056\u0077\u005e\u0044\u006f\u0076\u005e\u0062\u007b\u0063\u0051\u0036\u004f\u0066\u004b\u0041\u003a\u0063\u0048\u004a\u0060\u006b\u002a\u0077\u0028\u0070\u0057\u003e\u0079\u0021\u0052\u0031\u0057\u0051\u0042\u0021\u004c\u0028\u0043\u002e\u006b\u0068\u003f\u0051\u0021\u003d\u0032\u0031\u0039\u006b\u0041\u0040\u0032\u002c\u004e\u004c\u007e\u0073\u003c\u003e\u0062\u0021\u006d\u0039\u0050\u0051\u0034\u0040\u005f\u005a\u0053\u0063\u0044\u006b\u006f\u004b\u005d\u0042\u005a\u0058\u0042\u0033\u0041\u005d\u0049\u0048\u0040\u005c\u0021\u0048\u005f\u006f\u0023\u006a\u0038\u0046\u0069\u003d\u004b\u0058\u005e\u005f\u0025\u0022\u0076\u0032\u003e\u0032\u0027\u0033\u005c\u0030\u007b\u0032\u005f\u0064\u004d\u002d\u006a\u006b\u0063\u0075\u004e\u007d\u004a\u0044\u0020\u003a\u0067\u005c\u0028\u0075\u004a\u0062\u0076\u0077\u006c\u0064\u007b\u0037\u0042\u0031\u006f\u0059\u0026\u0044\u005f\u007e\u003a\u0041\u005e\u0021\u0031\u006f\u004d\u004a\u0057\u0042\u007d\u004b\u0057\u0077\u0071\u006b\u0077\u0040\u0060\u0045\u0043\u0059\u0021\u0026\u0078\u0063\u0061\u003b\u005b\u0077\u0026\u0051\u0038\u003b\u0033\u0049\u0074\u0021\u004b\u0031\u0028\u002d\u0057\u005b\u0063\u0038\u006a\u004d\u0032\u0054\u005c\u0071\u0034\u007e\u0044\u007e\u0027\u0065\u002c\u003c\u0022\u004f\u004f\u0043\u0033\u0044\u0044\u0042\u006c\u0037\u0026\u004e\u0031\u0043\u002c\u004e\u0075\u0054\u0071\u0025\u0071\u0057\u0055\u004b\u0030\u0051\u0073\u003d\u0026\u007a\u003e\u003c\u005b\u005a\u0041\u002f\u006c\u0044\u0070\u006f\u0057\u006c\u005e\u002f\u002b\u0063\u006b\u0027\u007d\u004d\u007b\u002a\u0045\u0064\u0061\u004b\u0054\u0039\u0032\u0029\u0069\u003c\u0053\u006d\u0025\u0021\u0026\u006b\u0072\u0033\u0027\u0051\u004a\u0037\u002d\u0026\u0027\u0042\u0032\u0053\u0035\u006e\u005d\u0025\u0053\u0077\u005d\u0052\u0062\u007c\u004b\u0072\u007a\u007b\u0028\u005c\u002c\u0060\u0071\u0064\u0043\u007a\u0022\u002c\u0060\u0043\u0067\u0074\u0074\u0073\u002d\u007c\u0050\u0030\u0079\u004c\u0024\u0059\u0039\u0040\u004c\u004f\u0062\u0050\u0062\u0060\u003a\u0063\u0023\u004d\u002e\u0069\u0070\u0050\u0054\u0026\u0041\u004e\u007a\u0020\u0057\u0074\u0065\u0076\u005b\u0026\u0046\u002a\u0038\u004c\u0027\u004d\u0043\u002b\u0034\u003e\u0053\u002e\u0034\u0075\u0063\u0067\u0045\u0076\u0065\u002e\u0069\u005c\u0056\u0063\u0061\u006c\u004d\u006f\u005b\u0027\u0030\u0044\u007e\u0033\u0038\u003f\u0077\u002f\u003e\u0066\u0056\u003f\u0023\u0062\u007d\u0062\u003f\u0076\u0050\u0040\u0048\u004e\u002d\u0077\u0049\u002d\u0021\u004c\u003d\u0049\u0027\u0073\u006f\u0066\u0053\u0020\u0055\u007d\u0028\u0049\u0033\u0077\u004b\u005e\u0050\u0071\u003b\u002e\u0069\u0078\u0051\u0042\u0044\u003a\u004d\u0046\u0073\u0066\u0033\u0046\u0057\u0030\u0047\u0063\u0057\u0031\u0040\u0072\u004f\u0036\u003e\u0069\u0056\u005e\u006e\u0043\u0074\u0077\u002f\u0029\u0038\u007e\u0076\u0072\u005e\u0028\u0075\u0050\u0076\u0053\u0069\u0075\u0046\u0026\u0065\u0025\u0054\u006a\u0067\u004a\u0032\u0053\u006a\u0025\u0069\u0021\u0028\u0025\u0049\u0032\u0042\u004b\u0067\u0060\u004a\u0025\u002a\u003c\u004a\u002a\u004e\u007c\u004f\u0077\u0050\u006b\u0076\u006b\u003b\u007b\u0043\u0029\u0053\u003b\u0042\u0057\u0064\u005a\u0029\u006b\u0052\u0044\u0038\u0035\u006e\u0076\u0036\u0075\u0020\u0053\u004f\u0056\u0075\u002b\u0045\u0044\u003a\u004d\u004f\u002a\u0050\u004b\u0026\u0054\u0027\u0038\u002e\u0038\u0074\u0033\u002b\u0069\u0064\u0029\u004d\u003a\u003f\u004a\u0028\u0070\u0062\u0029\u004b\u002b\u007c\u0052\u005f\u0052\u006a\u0052\u0057\u006e\u0041\u0027\u004c\u006f\u003c\u002d\u0077\u0052\u0049\u0059\u0050\u006d\u0059\u0049\u006c\u0073\u005e\u0042\u0020\u006d\u004c\u006f\u0049\u005f\u004e\u0033\u006a\u0077\u004a\u0047\u003a\u0066\u003f\u0047\u0052\u007d\u0048\u0062\u002c\u0030\u0021\u007b\u0030\u0064\u0053\u003c\u0029\u004b\u005f\u007a\u0071\u0023\u0076\u0078\u006a\u006f\u0063\u0021\u002e\u0052\u003b\u0039\u004b\u0051\u0035\u0024\u006e\u007c\u0029\u0059\u0050\u006b\u0069\u0048\u0055\u0071\u002e\u006a\u003f\u0044\u006d\u004b\u0042\u0054\u0045\u0047\u0051\u002c\u0029\u002b\u007a\u0027\u0040\u0039\u004c\u0036\u0073\u006c\u0036\u0063\u0048\u003e\u004a\u007e\u0042\u007a\u0059\u0075\u0046\u007c\u0043\u002d\u002d\u0029\u0036\u0060\u0065\u006a\u006e\u004e\u0073\u0062\u0059\u0046\u0033\u0059\u006f\u0073\u0025\u003d\u0064\u006a\u005c\u004c\u0056\u0077\u007e\u0055\u0077\u0024\u002a\u003e\u0045\u0035\u005d\u006f\u0051\u0075\u0079\u0046\u0044\u0030\u0072\u0045\u002b\u006e\u0045\u006a\u0058\u007c\u002b\u0049\u0064\u0029\u003e\u0034\u004d\u0023\u004e\u0023\u0047\u002f\u002a\u0046\u004b\u0068\u0069\u0072\u0051\u0054\u006d\u0026\u0060\u0024\u0075\u0051\u0049\u004e\u005b\u005d\u0042\u0028\u0054\u0069\u006f\u0041\u0048\u005e\u006b\u0032\u0069\u0020\u0055\u0028\u002e\u0054\u003a\u0072\u0034\u007b\u0065\u004f\u0030\u0043\u0076\u0032\u0022\u004d\u0063\u006b\u002c\u0062\u002e\u006b\u0056\u0068\u0034\u0066\u0074\u003d\u0034\u0061\u0034\u0036\u0051\u0039\u0035\u002c\u0023\u004e\u0027\u0025\u004c\u0050\u0070\u006c\u004b\u0060\u0020\u007d\u002f\u006b\u003f\u0057\u0029\u003a\u0034\u0063\u0052\u0067\u006a\u0063\u006e\u0038\u0020\u0068\u0056\u0063\u0064\u0031\u0059\u0047\u0050\u0049\u0039\u002e\u0052\u007b\u0046\u0071\u0026\u002a\u005d\u002b\u004a\u0029\u0056\u0045\u0066\u005d\u0077\u0059\u0061\u0072\u0079\u006d\u0035\u0068\u0065\u0066\u0069\u0068\u006e\u0057\u002d\u0056\u004a\u0063\u0040\u0027\u0054\u0065\u0020\u0025\u0067\u002b\u0077\u0041\u004c\u003b\u0078\u006e\u002e\u0043\u0057\u002e\u006c\u0024\u004e\u0078\u0023\u003d\u0054\u003f\u0064\u003f\u0031\u0048\u0026\u003e\u0042\u0074\u005a\u0023\u0073\u0060\u003c\u0024\u0026\u004e\u006c\u005e\u0067\u002f\u0054\u002d\u0076\u002d\u0028\u0046\u0060\u007a\u0032\u0021\u005d\u005c\u005a\u0066\u0076\u006b\u0077\u0069\u0066\u0035\u0077\u0054\u002b\u0039\u0079\u0059\u005c\u0025\u003e\u0046\u006b\u006f\u0053\u003c\u0075\u0020\u0049\u004d\u005b\u004c\u0069\u0057\u003d\u006e\u0037\u0028\u002a\u0077\u002a\u0064\u0020\u0045\u0026\u0051\u003d\u0050\u0073\u0077\u0058\u002b\u003a\u0035\u0034\u0078\u007c\u005a\u0067\u0022\u007d\u0070\u0067\u0062\u002d\u007c\u0049\u0078\u0066\u003e\u0071\u0032\u0040\u006e\u003a\u002d\u002b\u0057\u0029\u0032\u0070\u0051\u0023\u0048\u007d\u0036\u0035\u0075\u004c\u0063\u006d\u0066\u0044\u0020\u0023\u0069\u0052\u0034\u003f\u0050\u0079\u003b\u002a\u006c\u002b\u0054\u004a\u007a\u0078\u0067\u005b\u0065\u0079\u0062\u003a\u002d\u003e\u0061\u006d\u0077\u004b\u0060\u007c\u003b\u0027\u0038\u0048\u0061\u0047\u0041\u0070\u005c\u0066\u0055\u0069\u0022\u0034\u0076\u0067\u0066\u0075\u0040\u0079\u0047\u007a\u0043\u0076\u0079\u0036\u007c\u0075\u002b\u006a\u0071\u0041\u0030\u004b\u0059\u0046\u0032\u0050\u005b\u0060\u0055\u002e\u0039\u0044\u0053\u0076\u0051\u0030\u005f\u003b\u0037\u0073\u0045\u0061\u007d\u006d\u0056\u0039\u0066\u0043\u003e\u0074\u0030\u0063\u0056\u0078\u0040\u005e\u0039\u0058\u0070\u005e\u0059\u007b\u0023\u0042\u0059\u0061\u0049\u003d\u0067\u007d\u003a\u002b\u0059\u0076\u0031\u007c\u006b\u004a\u0075\u0056\u0020\u0028\u0034\u0057\u004b\u0055\u0075\u0049\u0044\u0056\u007a\u006a\u0022\u0055\u0048\u0021\u004c\u003b\u002c\u0050\u0033\u0022\u0027\u0037\u0065\u006e\u005f\u0067\u0069\u0056\u0030\u0061\u0056\u0045\u0047\u004d\u0043\u0054\u0078\u006c\u005c\u0071\u002c\u0044\u004e\u0075\u005b\u0023\u0056\u0059\u0030\u0032\u0079\u0042\u003c\u0053\u005f\u006e\u0077\u003b\u0076\u0033\u0036\u003d\u0021\u0034\u0052\u0065\u0072\u0067\u0068\u0020\u007b\u0035\u006b\u002c\u0058\u0072\u006a\u0073\u0074\u003d\u005e\u003d\u0031\u0023\u0064\u0035\u0046\u0057\u0041\u0079\u0034\u0061\u0064\u0078\u0045\u0046\u0055\u004c\u004a\u0024\u0029\u006b\u0035\u0031\u004d\u005d\u0044\u0061\u0047\u003e\u0046\u005e\u003e\u0069\u0079\u0062\u0074\u0053\u0024\u0071\u0036\u0058\u0028\u0059\u0065\u0053\u0048\u0075\u007a\u0027\u0028\u0065\u0077\u0056\u005d\u004e\u0052\u004d\u006c\u0037\u005b\u0073\u0069\u0072\u002e\u0069\u004f\u006d\u0076\u0071\u0065\u0069\u0025\u003e\u004a\u0034\u0051\u0040\u002d\u002a\u0056\u0074\u005e\u0061\u0059\u0023\u002b\u003e\u005d\u0075\u0045\u0030\u0061\u007b\u0062\u007a\u0041\u0037\u0071\u0060\u0024\u0041\u0028\u0044\u004e\u0026\u0038\u0062\u0046\u002e\u0034\u0049\u0067\u0042\u0030\u005f\u0058\u0079\u0065\u0024\u006e\u0041\u0057\u003e\u0062\u0027\u0020\u007e\u0043\u0037\u005b\u0043\u007d\u0061\u002e\u0058\u0070\u006f\u0057\u0073\u0058\u0059\u0076\u005f\u003d\u005b\u0048\u0021\u007c\u0049\u003e\u002b\u0065\u0052\u0023\u003b\u003b\u005b\u0076\u0069\u0021\u0027\u0066\u0062\u0026\u0063\u006f\u0035\u0025\u0044\u006d\u0032\u003d\u007a\u0040\u0069\u0042\u0045\u0069\u0058\u002b\u0049\u006e\u0021\u0056\u002f\u0073\u0060\u0052\u004e\u0062\u0059\u0045\u0028\u007d\u0079\u0059\u005f\u0057\u006b\u0076\u0065\u0031\u0038\u007c\u0031\u0028\u0075\u0064\u005d\u0041\u0029\u005b\u002d\u007b\u005d\u0063\u0060\u0028\u006b\u0037\u0065\u005e\u0055\u003c\u0028\u002e\u0024\u0077\u0025\u002d\u003f\u0053\u0025\u0077\u005d\u004e\u007a\u0054\u0025\u0063\u0035\u006e\u002e\u006a\u0036\u007e\u0032\u006b\u004f\u0021\u002a\u0046\u0074\u0056\u0075\u004b\u0039\u004f\u0077\u006c\u007e\u006a\u0036\u0030\u0075\u0025\u0063\u0055\u0024\u0078\u004a\u006d\u007c\u006d\u0078\u0054\u006d\u0079\u0077\u0050\u0041\u006b\u0043\u0021\u0028\u0048\u004f\u0035\u004c\u0048\u006b\u005c\u0078\u0078